<script setup>
import { ref, computed } from 'vue'
import zhCN from 'ant-design-vue/es/locale/zh_CN'
import dayjs from 'dayjs'
import 'dayjs/locale/zh-cn'
dayjs.locale('zh-cn')
import { message, Modal } from 'ant-design-vue'
import { AppstoreOutlined, BankOutlined, FileTextOutlined, RobotOutlined, PlusOutlined, RightOutlined, CheckOutlined, SafetyCertificateOutlined, BellOutlined, QuestionCircleOutlined, SearchOutlined, ArrowLeftOutlined, UploadOutlined, ThunderboltFilled, CheckCircleFilled, ClockCircleOutlined, DeleteOutlined, EditOutlined, ExportOutlined } from '@ant-design/icons-vue'
const path=ref(''), step=ref(0), business=ref('起降'), summary=ref(''), contract=ref(null), month=ref(null), contractOpen=ref(false), searchName=ref(''), searchCode=ref(''), query=ref({name:'',code:''}), selectedKeys=ref([]), invoices=ref([]), busy=ref(false), checked=ref(false), verified=ref(false), result=ref(''), supplier=ref('SUP-001'), supplierConfirmed=ref(false), completed=ref(false), draft=ref(false), detailOpen=ref(false), currentInvoice=ref({}), virtualOpen=ref(false), editing=ref(-1), virtuals=ref([]), virtualForm=ref({}), help=ref(false), notesOpen=ref(false), scenario=ref('success'), chat=ref('')
const contracts=[{key:'1',name:'首都机场航空地面服务协议',code:'HT-2026-00128',type:'机场合同',status:'履行中',partner:'北京首都国际机场股份有限公司',date:'2026.01.01 — 2026.12.31'},{key:'2',name:'华东地区航路保障服务协议',code:'HT-2026-00086',type:'航管合同',status:'履行中',partner:'中国民用航空华东地区空中交通管理局',date:'2026.01.01 — 2026.12.31'},{key:'3',name:'企业数字化技术服务合同',code:'HT-2026-00201',type:'其他合同',status:'履行中',partner:'云帆科技（北京）有限公司',date:'2026.06.01 — 2027.05.31'},{key:'4',name:'机场地面综合服务协议（历史）',code:'HT-2025-00039',type:'机场合同',status:'已到期',partner:'北京首都国际机场股份有限公司',date:'2025.01.01 — 2025.12.31'}]
const filteredContracts=computed(()=>contracts.filter(c=>c.name.includes(query.value.name)&&c.code.toLowerCase().includes(query.value.code.toLowerCase())))
const isAirport=computed(()=>contract.value?.type==='机场合同')
const labels=computed(()=>path.value==='virtual'?['选择合同','录入明细','确认创建']:['业务信息','关联合同','发票核对','验证与确认'])
const total=computed(()=>{const amounts={};(path.value==='virtual'?virtuals.value:invoices.value).forEach(i=>{amounts[i.currency]=(amounts[i.currency]||0)+Math.round(Number(i.amount||0)*100)});return Object.entries(amounts).map(([c,a])=>({currency:c,amount:(a/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}))})
const contractColumns=[{title:'合同名称 / 编号',key:'name'},{title:'合同类型',dataIndex:'type'},{title:'状态',key:'status'}]
const invoiceColumns=[{title:'发票信息',key:'invoice'},{title:'币种',dataIndex:'currency',width:75},{title:'含税金额',key:'amount',align:'right'},{title:'状态',key:'status'},{title:'操作',key:'action',width:90}]
const virtualColumns=[{title:'摘要',dataIndex:'summary'},{title:'服务月',key:'months'},{title:'币种',dataIndex:'currency'},{title:'原币金额',key:'amount',align:'right'},{title:'操作',key:'action'}]
const money=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})
function reset(){path.value='';step.value=0;contract.value=null;summary.value='';month.value=null;invoices.value=[];virtuals.value=[];result.value='';verified.value=false;checked.value=false;supplierConfirmed.value=false;completed.value=false;draft.value=false}
function newSession(){if(path.value)Modal.confirm({title:'开始新的付款会话？',content:'当前原型中的未提交信息将被清空。',okText:'开始新会话',cancelText:'继续当前会话',onOk:reset});else reset()}
function choose(p){path.value=p;step.value=0}
function nextBusiness(){if(!summary.value.trim())return message.warning('请填写付款摘要');step.value=1}
function openContract(){selectedKeys.value=contract.value?[contract.value.key]:[];contractOpen.value=true}
function confirmContract(){const c=contracts.find(c=>c.key===selectedKeys.value[0]);if(!c)return;if(c.status!=='履行中')return message.warning('已到期合同是否可付款待业务确认，原型暂不放行');const apply=()=>{contract.value=c;month.value=null;invalidate();contractOpen.value=false;step.value=path.value==='virtual'?1:1};if(contract.value&&contract.value.key!==c.key)Modal.confirm({title:'确认变更关联合同？',content:'附件及录入数据将保留，服务月、供应商确认及整批验证结果将失效，需要重新核对。',okText:'确认变更',cancelText:'取消',onOk:apply});else{contract.value=c;contractOpen.value=false;if(path.value==='virtual')step.value=1}}
function invalidate(){verified.value=false;checked.value=false;result.value='';supplierConfirmed.value=false;completed.value=false;invoices.value.forEach(i=>i.status=i.parsed?'待核对':'待解析')}
function nextContract(){if(!contract.value)return message.warning('请选择合同');if(isAirport.value&&!month.value)return message.warning('请选择演示服务月');step.value=2}
function addFile(file){invoices.value.push({key:Date.now()+Math.random(),file:file.name,parsed:false,currency:'',amount:null,status:'待解析'});invalidate();return false}
function demo(foreign=false){invoices.value.push({key:Date.now()+Math.random(),file:foreign?'Invoice_Ground_Service.pdf':`电子发票_机场服务_${invoices.value.length+1}.pdf`,foreign,parsed:false,currency:'',amount:null,status:'待解析'});invalidate()}
async function parse(){if(!invoices.value.length)return;busy.value=true;await new Promise(r=>setTimeout(r,1000));invoices.value=invoices.value.map((i,n)=>i.parsed?i:{...i,parsed:true,number:i.foreign?'INV-2026-00128':`026110000000${String(128001+n).padStart(8,'0')}`,code:'',issue:'2026-10-08',received:'2026-10-08',checkCode:'',currency:i.foreign?'USD':'CNY',invoiceAmount:i.foreign?6800:(n%2?18600:42800),amount:i.foreign?6800:(n%2?18600:42800),net:i.foreign?null:(n%2?17547.17:40377.36),tax:i.foreign?null:(n%2?1052.83:2422.64),vendor:i.foreign?'Global Airport Services Ltd.':contract.value.partner,taxId:i.foreign?'':'91110000101100000X',status:'待核对'});busy.value=false;message.success('演示解析完成，请逐张核对票据信息')}
function removeInvoice(key){invoices.value=invoices.value.filter(i=>i.key!==key);invalidate()}
function editInvoice(i){currentInvoice.value={...i};detailOpen.value=true}
function saveInvoice(){if(!currentInvoice.value.number||!currentInvoice.value.currency||currentInvoice.value.amount===null)return message.warning('请补全票号、币种及金额');invoices.value=invoices.value.map(i=>i.key===currentInvoice.value.key?{...currentInvoice.value,status:'待核对'}:i);invalidate();detailOpen.value=false;message.success('核对信息已保存，请重新确认整批数据')}
async function validate(){if(invoices.value.some(i=>i.foreign)){result.value='foreign';return}busy.value=true;result.value='validating';await new Promise(r=>setTimeout(r,1200));busy.value=false;if(scenario.value==='failure'){result.value='failed';verified.value=false;invoices.value.forEach((i,n)=>i.status=n===0?'重复发票':'已回滚')}else if(scenario.value==='timeout'){result.value='unknown';verified.value=false}else{result.value='success';verified.value=true;invoices.value.forEach(i=>i.status='验证通过');step.value=3}}
function continueEntry(){invalidate();step.value=2;invoices.value.forEach(i=>i.status='待核对')}
function openVirtual(index=-1){editing.value=index;virtualForm.value=index>=0?{...virtuals.value[index]}:{currency:'CNY',amount:null,summary:'',start:null,end:null};virtualOpen.value=true}
function saveVirtual(){const f=virtualForm.value;if(!f.currency||f.amount===null||f.amount===undefined||!f.summary?.trim())return message.warning('请填写币种、原币金额和摘要');if(Number(f.amount)<=0)return message.warning('零额、负额规则待财务确认，演示暂仅支持正数');if(isAirport.value&&(!f.start||!f.end))return message.warning('机场合同必须填写服务起止月份');if(f.start&&f.end&&f.start>f.end)return message.warning('开始月份不得晚于结束月份');if(editing.value>=0)virtuals.value[editing.value]={...f};else virtuals.value.push({...f,key:Date.now()});virtualOpen.value=false;completed.value=false}
function deleteVirtual(index){Modal.confirm({title:'删除这条虚拟发票？',content:'删除后会重新计算明细合计。',okText:'删除',okType:'danger',cancelText:'取消',onOk(){virtuals.value.splice(index,1);completed.value=false}})}
function finishVirtual(){if(isAirport.value&&virtuals.value.some(i=>!i.start||!i.end||i.start>i.end))return message.warning('合同已变更，请逐条补全有效服务起止月份');if(!virtuals.value.length)return message.warning('请至少录入一条虚拟发票');completed.value=true;step.value=2}
async function createDraft(){if(!contract.value||!completed.value)return;if(path.value==='real'&&(!verified.value||!supplierConfirmed.value))return message.warning('请先完成整批验证及供应商确认');busy.value=true;await new Promise(r=>setTimeout(r,700));busy.value=false;draft.value=true}
function sendChat(){if(!chat.value.trim())return;message.info('请通过上方操作卡片完成关键选择，助手不会代替你确认付款数据');chat.value=''}
</script>

<template>
<a-config-provider :locale="zhCN" :theme="{token:{colorPrimary:'#3563e9',borderRadius:8,fontFamily:'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, PingFang SC, Microsoft YaHei, sans-serif',colorText:'#26334b'}}">
<div class="shell">
<aside class="sidebar"><div class="brand"><div class="brand-icon"><BankOutlined /></div><span>云帆财务<span class="brand-sub">FINANCE WORKSPACE</span></span></div><div class="workspace-label">工作空间 <span>企业版</span></div><div class="nav-item" @click="message.info('当前原型聚焦 AI 智能付款流程')"><AppstoreOutlined />工作台</div><div class="nav-item selected"><RobotOutlined />AI 智能付款 <span class="new-badge">NEW</span></div><div class="nav-item" @click="notesOpen=true"><FileTextOutlined />付款申请 <span class="nav-count">12</span></div><div class="nav-item" @click="openContract"><BankOutlined />合同管理</div><div class="sidebar-line"></div><div class="history-label">最近会话 <a-tooltip title="会话仅保留于当前页面"><QuestionCircleOutlined /></a-tooltip></div><div class="history active"><span class="history-dot"></span>{{ contract ? contract.name : '新建付款申请' }}<small>当前会话</small></div><div class="sidebar-bottom"><div class="security"><SafetyCertificateOutlined /><span>企业数据安全保护<small>权限范围内访问 · 全程可追踪</small></span></div><div class="profile"><a-avatar style="background:#e9efff;color:#4567b2">林</a-avatar><span>林晓<small>财务共享中心 · 经办人</small></span><span class="online-dot"></span></div></div></aside>
<div class="main-shell"><header class="topbar"><div>财务工作台 <RightOutlined /><b>AI 智能付款</b></div><div class="header-actions"><a-tag color="blue">交互原型</a-tag><a-button type="text" @click="help=true"><QuestionCircleOutlined /> 使用指南</a-button><a-badge dot><BellOutlined /></a-badge><a-divider type="vertical"/><a-avatar size="small" style="background:#eef2ff;color:#5368a4">林</a-avatar></div></header>
<main><div class="page-heading"><div><div class="title-line"><h1>AI 智能付款</h1><span class="ai-badge"><ThunderboltFilled /> AI ASSISTANT</span></div><p>从票据到付款单，让每一步都更简单。</p></div><a-button @click="newSession"><PlusOutlined /> 新建会话</a-button></div>
<div class="content-grid"><section class="conversation"><div class="conversation-top"><span class="green-dot"></span><b>智能付款助手</b><span class="session-id">当前会话 · PAY-20261015</span><a-button type="text" size="small" @click="notesOpen=true">需求说明 <ExportOutlined /></a-button></div>
<div v-if="draft" class="draft-page"><a-button type="link" @click="draft=false"><ArrowLeftOutlined /> 返回付款助手</a-button><div class="draft-icon"><CheckCircleFilled /></div><h2>付款信息已带入</h2><p>请核对以下信息，并按原流程提交审批。</p><a-alert message="起草预览 · 尚未提交审批，也未发生实际付款" type="info" show-icon/><a-descriptions title="审批付款单 · 起草" bordered :column="1" class="draft-details"><a-descriptions-item label="申请人">林晓 / 财务共享中心</a-descriptions-item><a-descriptions-item label="付款方式">{{path==='real'?'真实发票付款':'虚拟发票付款'}}</a-descriptions-item><a-descriptions-item label="关联合同">{{contract.name}}<br/>{{contract.code}}</a-descriptions-item><a-descriptions-item v-if="path==='real'" label="业务 / 摘要">{{business}} / {{summary}}</a-descriptions-item><a-descriptions-item v-if="path==='real'" label="财务供应商">{{contract.partner}}（{{supplier}}）</a-descriptions-item><a-descriptions-item v-if="month" label="服务月">{{month}}</a-descriptions-item><a-descriptions-item label="金额合计"><div v-for="t in total" :key="t.currency">{{t.currency}} {{t.amount}}</div></a-descriptions-item></a-descriptions><a-table size="small" :pagination="false" :data-source="path==='real'?invoices:virtuals" :columns="[{title:'明细',key:'desc'},{title:'币种',dataIndex:'currency'},{title:'金额',key:'amount'}]"><template #bodyCell="{column,record}"><template v-if="column.key==='desc'">{{record.number||record.summary}}<small class="block muted">{{record.file||[record.start,record.end].filter(Boolean).join(' 至 ')}}</small></template><template v-if="column.key==='amount'">{{money(record.amount)}}</template></template></a-table><div class="draft-footer"><SafetyCertificateOutlined /> 原型演示：未连接实际审批与支付系统</div></div>
<template v-else><div v-if="path" class="stepper"><a-steps size="small" :current="step" :items="labels.map(title=>({title}))"/></div><div class="chat-body"><div class="assistant-message"><div class="assistant-avatar"><RobotOutlined /></div><div><div class="speaker">付款助手 <span>AI</span></div><p v-if="!path">你好，林晓 👋<br/>我可以协助你整理合同与发票信息，快速起草付款单。<br/>请选择本次付款方式，我们一起开始。</p><p v-else-if="path==='real'&&step===0">好的，我们来处理真实发票付款。<br/>请先选择业务类型，并填写本次付款的摘要。</p><p v-else-if="!contract">请关联本次付款的合同。<br/>我会根据合同类型，为你展示需要补充的信息。</p><p v-else-if="completed">信息已整理完成，请最后核对付款摘要。<br/>确认后，我将为你打开付款单起草页面。</p><p v-else-if="verified">本批发票已全部通过演示验证。<br/>请核对财务供应商，并确认是否已完成全部发票录入。</p><p v-else-if="path==='virtual'">已关联 {{contract.name}}。<br/>请录入虚拟发票信息，支持添加多条记录。</p><p v-else-if="step===1">合同已关联，请核对合同信息{{isAirport?'并补充服务月':''}}。</p><p v-else>请上传发票附件，或使用示例票据体验。<br/>解析后请逐张核对，确认无误后再进行整批验证。</p></div></div>
<div v-if="!path" class="entry-area"><div class="path-card" @click="choose('real')" role="button" tabindex="0" @keydown.enter="choose('real')"><div class="path-icon blue"><FileTextOutlined /></div><div><h3>真实发票付款 <span>常用</span></h3><p>上传真实票据，AI 辅助解析与核对</p><div class="path-tags">批量上传 <i>·</i> 发票验证 <i>·</i> 自动回填</div></div><RightOutlined /></div><div class="path-card" @click="choose('virtual')" role="button" tabindex="0" @keydown.enter="choose('virtual')"><div class="path-icon purple"><BankOutlined /></div><div><h3>虚拟发票付款</h3><p>无需真实票据，直接录入付款明细</p><div class="path-tags">多条明细 <i>·</i> 服务月管理 <i>·</i> 按币种汇总</div></div><RightOutlined /></div><div class="entry-note"><SafetyCertificateOutlined /> 仅创建付款草稿，审批与实际付款仍按现有流程进行。</div><div class="flow-preview"><div class="eyebrow">更清晰的付款体验</div><div><span><b>01</b> 关联业务合同</span><RightOutlined /><span><b>02</b> 核对付款信息</span><RightOutlined /><span><b>03</b> 一键起草回填</span></div></div></div>
<div v-else class="operation-area">
<div class="path-label"><a-tag :color="path==='real'?'blue':'purple'">{{path==='real'?'真实发票付款':'虚拟发票付款'}}</a-tag><a-button type="link" size="small" @click="newSession">切换付款方式</a-button></div>
<div v-if="path==='real'&&step===0" class="operation-card"><div class="card-heading"><span class="section-number">01</span><h3>填写业务信息</h3></div><a-form layout="vertical"><a-form-item label="业务类型" required><a-radio-group v-model:value="business" class="business-radio"><a-radio-button value="起降">起降业务</a-radio-button><a-radio-button value="航管">航管业务</a-radio-button><a-radio-button value="其他业务">其他业务</a-radio-button></a-radio-group></a-form-item><a-form-item label="付款摘要" required><a-textarea v-model:value="summary" placeholder="例如：2026 年 9 月首都机场起降及地面服务费" :rows="3"/><div class="field-hint">简要说明付款用途，信息将带入付款单。</div></a-form-item></a-form><div class="card-footer"><span>下一步：关联合同</span><a-button type="primary" @click="nextBusiness">下一步 <RightOutlined /></a-button></div></div>
<div v-if="(path==='real'&&step===1)||(path==='virtual'&&!contract)" class="operation-card"><div class="card-heading"><span class="section-number">{{path==='real'?'02':'01'}}</span><h3>关联合同</h3><a-tag>权限内可见</a-tag></div><template v-if="contract"><div class="contract-picked"><div class="contract-symbol"><FileTextOutlined /></div><div><h4>{{contract.name}}</h4><p>{{contract.code}} <a-tag color="blue">{{contract.type}}</a-tag><a-tag color="green">{{contract.status}}</a-tag></p><small>{{contract.date}}</small></div><a-button type="link" @click="openContract">更换</a-button></div><a-form v-if="isAirport" layout="vertical" class="month-form"><a-form-item label="服务月" required><a-date-picker v-model:value="month" picker="month" value-format="YYYY-MM" placeholder="选择服务月"/><div class="field-hint">原型暂以单月展示；服务月粒度与必填规则待财务确认（Q02）。</div></a-form-item></a-form></template><div v-else class="contract-empty"><BankOutlined /><h4>为付款关联一份合同</h4><p>仅展示你有权限访问的合同</p><a-button type="primary" @click="openContract">选择合同 <RightOutlined /></a-button></div><div v-if="path==='real'" class="card-footer"><a-button @click="step=0">上一步</a-button><a-button type="primary" :disabled="!contract" @click="nextContract">下一步 <RightOutlined /></a-button></div></div>
<template v-if="path==='real'&&step>=2&&!completed"><div class="operation-card"><div class="card-heading"><span class="section-number">03</span><h3>发票上传与核对</h3><a-tag>{{invoices.length}} 张发票</a-tag></div><template v-if="!verified"><a-upload-dragger :multiple="true" :show-upload-list="false" :before-upload="addFile"><p class="upload-icon"><UploadOutlined /></p><h4>点击或拖拽发票文件到此处</h4><p>支持批量选择，上传后手动发起解析</p></a-upload-dragger><div class="demo-line"><span>没有票据？使用脱敏示例体验完整流程</span><a-button type="link" size="small" @click="demo(false)"><PlusOutlined /> 添加示例发票</a-button></div></template><a-table v-if="invoices.length" :columns="invoiceColumns" :data-source="invoices" :pagination="false" size="small" :scroll="{x:560}"><template #bodyCell="{column,record}"><template v-if="column.key==='invoice'"><div class="invoice-name">{{record.parsed?record.number:record.file}}</div><small class="muted">{{record.parsed?record.vendor:'已加入本地演示 · 尚未解析'}}</small></template><template v-if="column.key==='amount'">{{record.parsed?money(record.amount):'—'}}</template><template v-if="column.key==='status'"><a-tag :color="verified?'green':record.status==='重复发票'?'red':'orange'">{{record.status}}</a-tag></template><template v-if="column.key==='action'"><a-button v-if="record.parsed" type="link" size="small" @click="editInvoice(record)">核对</a-button><a-button type="text" size="small" danger @click="removeInvoice(record.key)"><DeleteOutlined /></a-button></template></template></a-table><div v-if="invoices.length&&!verified" class="parse-actions"><a-checkbox v-if="invoices.every(i=>i.parsed)" v-model:checked="checked">我已逐张核对，确认信息无误</a-checkbox><span v-else class="muted">至少上传一张发票后可解析</span><a-button :loading="busy" :disabled="!invoices.length" @click="parse"><ThunderboltFilled /> {{invoices.every(i=>i.parsed)?'重新解析':'发票解析'}}</a-button></div><div v-if="result==='foreign'" class="result-box"><a-alert type="warning" show-icon message="国外 Invoice 放行规则待确认（Q07）" description="已完成演示解析，但不会自动判定税务验证通过。可核对字段；如需体验国内完整路径，请删除该示例后整批重验。"/></div><div v-if="result==='failed'" class="result-box"><a-alert type="error" show-icon message="整批验证失败 · 本次查重占用已模拟回滚" description="第 1 张发票存在重复记录。其他票据的通过结果已失效，请修正或重新上传后整批重验。"/></div><div v-if="result==='unknown'" class="result-box"><a-alert type="warning" show-icon message="验证结果待确认" description="模拟服务超时，当前不可创建。请切换演示场景为“全部通过”后查询结果。"/></div><div v-if="verified" class="result-box"><a-alert type="success" show-icon :message="`整批验证通过 · ${invoices.length} 张发票`" description="当前为模拟验证结果，未调用税务系统。"/></div><div v-if="!verified&&invoices.length" class="card-footer"><a-select v-model:value="scenario" size="small" style="width:170px" :options="[{value:'success',label:'演示：全部通过'},{value:'failure',label:'演示：失败与回滚'},{value:'timeout',label:'演示：验证超时'}]"/><a-button type="primary" :disabled="!checked||!invoices.every(i=>i.parsed)" :loading="busy" @click="validate">{{result==='unknown'?'查询验证结果':'发票验证'}} <SafetyCertificateOutlined /></a-button></div></div>
<div v-if="verified" class="operation-card"><div class="card-heading"><span class="section-number">04</span><h3>确认财务供应商</h3></div><a-form layout="vertical"><a-form-item label="合同关联的有效客商" required><a-select v-model:value="supplier" @change="supplierConfirmed=false" :options="[{value:'SUP-001',label:contract.partner+' · SUP-001'},{value:'SUP-002',label:contract.partner+'（结算主体） · SUP-002'}]"/></a-form-item></a-form><a-checkbox v-model:checked="supplierConfirmed">已核对财务供应商，与本次付款一致</a-checkbox><div class="card-footer"><a-button @click="continueEntry"><PlusOutlined /> 继续录入</a-button><a-button type="primary" :disabled="!supplierConfirmed" @click="completed=true">录入完成 <CheckOutlined /></a-button></div></div></template>
<div v-if="path==='virtual'&&contract&&!completed" class="operation-card"><div class="card-heading"><span class="section-number">02</span><h3>虚拟发票明细</h3><a-button type="primary" size="small" @click="openVirtual()"><PlusOutlined /> 新增明细</a-button></div><a-alert v-if="isAirport" type="info" show-icon message="当前为机场合同，请填写每条明细的服务起止月份。" style="margin-bottom:18px"/><a-table :columns="virtualColumns" :data-source="virtuals" :pagination="false" size="small" :scroll="{x:530}"><template #emptyText><div class="virtual-empty"><FileTextOutlined /><p>还没有付款明细</p><small>添加第一条虚拟发票，开始整理本次付款</small><br/><a-button type="link" @click="openVirtual()">新增明细</a-button></div></template><template #bodyCell="{column,record,index}"><template v-if="column.key==='months'">{{record.start?record.start+' 至 '+record.end:'不适用'}}</template><template v-if="column.key==='amount'">{{money(record.amount)}}</template><template v-if="column.key==='action'"><a-button size="small" type="link" @click="openVirtual(index)">编辑</a-button><a-button size="small" type="text" danger @click="deleteVirtual(index)"><DeleteOutlined /></a-button></template></template></a-table><div class="card-footer"><span class="muted">共 {{virtuals.length}} 条 · 按币种分别汇总</span><a-button type="primary" :disabled="!virtuals.length" @click="finishVirtual">录入完成 <CheckOutlined /></a-button></div></div>
<div v-if="completed" class="operation-card confirmation"><div class="confirmation-check"><CheckCircleFilled /></div><h2>付款信息已准备就绪</h2><p>已整理 {{path==='real'?invoices.length:virtuals.length}} {{path==='real'?'张发票':'条虚拟发票'}}，请核对后创建付款单。</p><div class="confirm-summary"><div><span>关联合同</span><b>{{contract.name}}</b></div><div v-for="t in total" :key="t.currency"><span>付款合计 · {{t.currency}}</span><strong>{{t.amount}}</strong></div></div><a-alert v-if="total.length>1" type="warning" show-icon message="多币种是否可合并一单待确认，此处仅展示回填预览。"/><div class="confirmation-actions"><a-button @click="completed=false">返回核对</a-button><a-button type="primary" size="large" :loading="busy" @click="createDraft"><ThunderboltFilled /> 一键 AI 创建付款单</a-button></div><small>信息将带入起草页面，仍需按原流程核对与提交审批。</small></div>
</div></div><div class="composer"><a-input v-model:value="chat" placeholder="告诉我你的付款需求，或通过上方卡片继续操作…" @press-enter="sendChat"><template #prefix><RobotOutlined /></template><template #suffix><a-button type="primary" size="small" @click="sendChat"><RightOutlined /></a-button></template></a-input><div><span><SafetyCertificateOutlined /> 企业数据受保护</span><span>AI 辅助整理，关键数据请人工核对</span></div></div></template></section>
<aside class="context-panel"><div class="overview-card"><div class="overview-title"><span><FileTextOutlined /> 本次付款概览</span><a-tag>{{draft?'已回填':completed?'待创建':'待完善'}}</a-tag></div><div class="context-field"><label>付款方式</label><b>{{path?(path==='real'?'真实发票付款':'虚拟发票付款'):'待选择'}}</b></div><div class="context-field"><label>关联合同 <a v-if="contract&&!draft" @click="openContract">更换</a></label><b v-if="contract">{{contract.name}}</b><span v-else class="placeholder">选择合同后自动展示</span><small v-if="contract">{{contract.code}}</small></div><div v-if="path==='real'&&summary" class="context-field"><label>业务摘要</label><b>{{business}} · {{summary}}</b></div><div v-if="month" class="context-field"><label>服务月</label><b>{{month}}</b></div><div class="amount-overview"><label>付款金额合计</label><template v-if="total.length"><div v-for="t in total" :key="t.currency"><span>{{t.currency}}</span><strong>{{t.amount}}</strong></div></template><div v-else><span>CNY</span><strong>— —</strong></div><small>{{path==='virtual'?virtuals.length:invoices.length}} {{path==='virtual'?'条明细':'张发票'}} <span>· 按原币种汇总</span></small></div><div class="overview-status"><ClockCircleOutlined /> {{draft?'已打开起草预览':completed?'等待你确认创建':'信息完善后可创建付款草稿'}}</div></div><div class="guide-card"><div class="guide-title"><SafetyCertificateOutlined /> 付款小贴士</div><ul><li>关联合同仅展示你有权限访问的数据。</li><li>真实发票需逐张核对，整批验证通过后才能继续。</li><li>起草完成不代表审批通过或实际付款。</li></ul><a @click="help=true">查看使用指南 <RightOutlined /></a></div><div class="prototype-note"><span class="prototype-dot"></span> 产品交互演示 <p>合同、发票与校验结果均为模拟数据；不会上传文件或产生真实业务记录。</p><a @click="notesOpen=true">查看设计边界与待确认事项</a></div></aside></div><footer class="page-footer">云帆财务工作台 <span>·</span> 让财务协作更高效、更安心</footer></main></div>
</div>
<a-modal v-model:open="contractOpen" title="关联合同" width="830px" :ok-button-props="{disabled:!selectedKeys.length}" ok-text="确定关联" cancel-text="取消" @ok="confirmContract"><p class="muted">选择一份合同用于本次付款，仅展示当前用户权限范围内的数据。</p><div class="contract-search"><a-input v-model:value="searchName" placeholder="合同名称" allow-clear/><a-input v-model:value="searchCode" placeholder="合同编号" allow-clear/><a-button type="primary" @click="query={name:searchName,code:searchCode}"><SearchOutlined /> 查询</a-button><a-button @click="searchName='';searchCode='';query={name:'',code:''}">重置</a-button></div><a-table :columns="contractColumns" :data-source="filteredContracts" :row-selection="{type:'radio',selectedRowKeys:selectedKeys,onChange:keys=>selectedKeys=keys,getCheckboxProps:r=>({disabled:r.status!=='履行中'})}" :pagination="{pageSize:4,showTotal:t=>`共 ${t} 份合同`}" size="middle"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><b>{{record.name}}</b><small class="block muted">{{record.code}}</small></template><template v-if="column.key==='status'"><a-tag :color="record.status==='履行中'?'green':'default'">{{record.status}}</a-tag></template></template></a-table><a-alert type="info" show-icon message="已到期合同的付款规则待确认，演示中暂不支持选择。"/></a-modal>
<a-drawer v-model:open="detailOpen" title="发票详情与人工核对" width="860" :destroy-on-close="true"><div class="invoice-detail"><div class="document-preview"><FileTextOutlined/><h3>电子发票</h3><div>演示票据示意 · 非原始附件</div><hr/><p>{{currentInvoice.vendor}}</p><p>票号：{{currentInvoice.number}}</p><p>开票日期：{{currentInvoice.issue}}</p><hr/><strong>{{currentInvoice.currency}} {{money(currentInvoice.amount)}}</strong><p class="muted">实际产品需在此接入原附件预览</p></div><a-form layout="vertical" class="invoice-form"><a-form-item v-for="f in [{k:'number',l:'发票号码'},{k:'code',l:'发票代码'},{k:'issue',l:'开票日期'},{k:'received',l:'到票日期'},{k:'checkCode',l:'发票校验码'},{k:'currency',l:'币种'},{k:'invoiceAmount',l:'发票金额'},{k:'amount',l:'含税金额'},{k:'net',l:'不含税金额'},{k:'tax',l:'税额'},{k:'vendor',l:'开票供应商'},{k:'taxId',l:'销方税号'}]" :key="f.k" :label="f.l"><a-select v-if="f.k==='currency'" v-model:value="currentInvoice[f.k]" :options="['CNY','USD','EUR','HKD'].map(value=>({value,label:value}))"/><a-input-number v-else-if="['invoiceAmount','amount','net','tax'].includes(f.k)" v-model:value="currentInvoice[f.k]" :precision="2" style="width:100%"/><a-date-picker v-else-if="['issue','received'].includes(f.k)" v-model:value="currentInvoice[f.k]" value-format="YYYY-MM-DD" style="width:100%"/><a-input v-else v-model:value="currentInvoice[f.k]" placeholder="未识别 / 不适用，请核对"/></a-form-item><a-alert type="warning" message="发票金额与含税金额在演示中暂映射为相同值，最终口径待财务确认（Q05）。"/></a-form></div><template #footer><div class="drawer-footer"><span>修改信息后，原批次验证结果将失效</span><a-button type="primary" @click="saveInvoice">保存核对信息</a-button></div></template></a-drawer>
<a-modal v-model:open="virtualOpen" :title="editing>=0?'编辑虚拟发票':'新增虚拟发票'" ok-text="保存本条" cancel-text="取消" @ok="saveVirtual"><a-form layout="vertical" style="margin-top:24px"><div class="form-row"><a-form-item label="发票币种" required><a-select v-model:value="virtualForm.currency" :options="['CNY','USD','EUR','HKD'].map(value=>({value,label:value}))"/></a-form-item><a-form-item label="原币金额" required><a-input-number v-model:value="virtualForm.amount" placeholder="请输入金额" :precision="2" style="width:100%"/></a-form-item></div><a-form-item label="摘要" required><a-textarea v-model:value="virtualForm.summary" placeholder="填写本条付款用途" :rows="3"/></a-form-item><div v-if="isAirport" class="form-row"><a-form-item label="开始月份" required><a-date-picker v-model:value="virtualForm.start" picker="month" value-format="YYYY-MM" style="width:100%"/></a-form-item><a-form-item label="结束月份" required><a-date-picker v-model:value="virtualForm.end" picker="month" value-format="YYYY-MM" style="width:100%"/></a-form-item></div><a-alert type="info" show-icon message="虚拟发票不进行真实票据解析及税务验证。"/></a-form></a-modal>
<a-modal v-model:open="help" title="使用指南" :footer="null"><div class="help-content"><h3>真实发票付款</h3><p>填写业务及摘要 → 关联合同 → 上传或添加示例 → 发票解析 → 逐张核对 → 整批验证 → 确认供应商 → 录入完成 → 起草预览。</p><h3>虚拟发票付款</h3><p>关联合同 → 添加多条明细 → 核对各币种金额 → 录入完成 → 起草预览。</p><h3>体验异常场景</h3><p>在验证按钮旁切换“失败与回滚”或“验证超时”，查看创建阻断与恢复流程。修改票据或变更合同会使原验证结果失效。</p><a-alert message="当前为前端交互原型，刷新页面将清空演示会话。" type="info" show-icon/></div></a-modal>
<a-drawer v-model:open="notesOpen" title="设计边界与待确认事项" width="500"><a-alert type="info" show-icon message="依据 AI智能付款 PRD V1.0 评审稿设计"/><div class="help-content"><h3>本次覆盖</h3><p>真实与虚拟两条路径、权限内合同查询、条件服务月、多条票据、12 项解析字段、逐票核对、整批验证失败回滚、供应商确认及起草回填预览。</p><h3>模拟与安全边界</h3><p>所有合同和发票均为虚构示例。选择的文件仅显示本地文件名，解析不读取文件内容。验证与回滚均为演示，不调用税务服务；付款单仅作回填预览。</p><h3>待财务确认</h3><p>Q01：到期合同是否可付款。<br/>Q02：真实发票服务月粒度。<br/>Q05：金额含义、精度及负额规则。<br/>Q06：查重占用及补偿边界。<br/>Q07：国外 Invoice 验证路径。<br/>Q08：多币种是否可合并一单。<br/>Q09–10：额外必填项及起草持久化方式。</p><h3>原型假设</h3><p>真实服务月暂用单月控件；非机场虚拟发票隐藏服务月；金额暂展示两位小数；不放行到期合同与负额票据。这些仅用于评审体验，不代表最终业务规则。</p></div></a-drawer>
</a-config-provider>
</template>
